window.AUTH=window.AUTH||{};window.AUTH["21-463"]={"d":"21-463","id":"2021/21-463","n":"Whole Woman's Health v. Jackson","briefs":[{"k":"petitioner","label":"Brief of petitioners Whole Woman's Health, et al.","date":"2021-10-27","url":"https://www.supremecourt.gov/DocketPDF/21/21-463/197889/20211027165628612_WWH%20v%20Jackson%20-%20Petitioners%20brief.pdf","side":"pet","n":81},{"k":"respondent","label":"Brief of respondent Penny Clarkston","date":"2021-10-27","url":"https://www.supremecourt.gov/DocketPDF/21/21-463/197885/20211027164908419_21-463%20Respondent%20Brief.pdf","side":"res","n":56},{"k":"respondent","label":"Brief of respondent Mark Lee Dickson","date":"2021-10-27","url":"https://www.supremecourt.gov/DocketPDF/21/21-463/197871/20211027163237426_WWH%20v%20Jackson%20Respondent%20Brief%20Dickson%20FINAL.pdf","side":"res","n":66},{"k":"reply","label":"Reply brief of petitioners Whole Woman's Health, et al.","date":"2021-10-29","url":"https://www.supremecourt.gov/DocketPDF/21/21-463/198275/20211029164631232_WWH%20v%20Jackson%20-%20Pet%20reply%20brief.pdf","side":"pet","n":44}],"opinion":"https://www.supremecourt.gov/opinions/21pdf/595us1r4_0861.pdf","tr":true,"items":[{"t":"case","label":"Agey v. Am. Liberty Pipe Line Co.","cite":"172 S.W.2d 972","y":1943,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.2d/172/972/","by":{"0":"35"}},{"t":"case","label":"Allen v. McCurry","cite":"449 U.S. 90","y":1980,"id":"1980/79-935","sc":1,"sum":"The Court of Appeals erred in holding that respondent's inability to obtain federal habeas corpus relief upon his Fourth Amendment claim renders the doctrine of collateral estoppel inapplicable to his § 1983 suit. Nothing in the language or legislative history of § 1983 discloses any congressional intent to deny binding effect to a state-court judgment or decision when the state court, acting within its proper …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Anderson v. Martin","cite":"375 U.S. 399","y":1964,"id":"1963/51","sc":1,"sum":"The compulsory designation by Louisiana of the race of the candidate on the ballot operates as a discrimination against appellants and is violative of the Equal Protection Clause of the Fourteenth Amendment of the Federal Constitution.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"Babbitt v. United Farm Workers Nat’l Union","cite":"442 U.S. 289","y":1979,"id":"1978/78-225","sc":1,"sum":"Appellees (a farmworkers' union, a union agent, farmworkers, and a union supporter) brought suit in Federal District Court in Arizona seeking a declaration of the unconstitutionality of various provisions of Arizona's farm labor statute, as well as of the entire statute, and an injunction against \"its enforcement. A three-judge court ruled unconstitutional on various grounds the provisions (1) specifying procedures …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"Baker v. Carr","cite":"369 U.S. 186","y":1962,"id":"1960/6","sc":1,"sum":"The Court found that redistricting issues present justiciable questions, and in which the Court reframed its political question doctrine.","sumSrc":"Oyez","by":{"0":"44","1":"25"}},{"t":"case","label":"Briscoe v. LaHue","cite":"460 U.S. 325","y":1983,"id":"1982/81-1404","sc":1,"sum":"Title 42 U. S. C. § 1983 (1976 ed., Supp. V) does not authorize a convicted state defendant to assert a claim for damages against a police officer for giving perjured testimony at the defendant's criminal trial.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23, 29"}},{"t":"case","label":"Brown v. Bd. of Educ.","cite":"349 U.S. 294","y":1955,"id":"1940-1955/349us294","sc":1,"sum":"The Court found that local jurisdictions were responsible for the integration of public schools under Brown v. Board of Education (I), but it must be implemented \"with all deliberate speed.\"","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Chancery Clerk of Chickasaw Cnty. v. Wallace","cite":"646 F.2d 151","y":1981,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/646/151/","op":1,"by":{"0":"13","1":"24, 25, 27, 32","2":"24, 29, 30"}},{"t":"case","label":"Citizens United v. FEC","cite":"558 U.S. 310","y":2010,"id":"2008/08-205","sc":1,"sum":"The Court held that corporate funding of independent political broadcasts in elections cannot be limited under the First Amendment.","sumSrc":"Oyez","by":{"0":"50","3":"12"}},{"t":"case","label":"City of Erie v. Pap’s A.M.","cite":"529 U.S. 277","y":2000,"id":"1999/98-1161","sc":1,"sum":"The Court held that Erie's public indecency ordinance did not violate any cognizable First Amendment protections of expressive conduct.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"Cooper v. Aaron","cite":"358 U.S. 1","y":1958,"id":"1957/1_misc","sc":1,"op":1,"ar":1,"sum":"The Court held that Arkansas officials were bound by federal court orders mandating desegregation.","sumSrc":"Oyez","by":{"0":"1, 3, 46"}},{"t":"case","label":"Czyzewski v. Jevic Holding Corp.","cite":"137 S. Ct. 973","y":2017,"id":"2016/15-649","sc":1,"sum":"The Court determined that bankruptcy court cannot authorize a distribution of settlement proceeds in a manner that does not comply with the Bankruptcy Code’s priority distribution scheme.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Dist. of Columbia v. Carter","cite":"409 U.S. 418","y":1973,"id":"1972/71-564","sc":1,"sum":"The District of Columbia is not a \"State or Territory\" within the meaning of 42 U. S. C. § 1983, and the Court of Appeals therefore erred insofar as that court sustained respondent's claims for deprivation of civil rights pursuant to that statute. Pp. 420-433. 144 U. S. App. D. C. 388, 447 F. 2d 358, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23, 24"}},{"t":"case","label":"Dombrowski v. Pfister","cite":"380 U.S. 479","y":1965,"id":"1964/52","sc":1,"sum":"Appellants, a civil rights organization and its executive director, brought suit in Federal District Court, in which other individuals later joined, for injunctive and declaratory relief to restrain appellees from prosecuting or threatening to prosecute them under Louisiana's Subversive Activities and Communist Control Law and Communist Propaganda Control Law, which they alleged violated their rights of free …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29","3":"15"}},{"t":"case","label":"Edelman v. Jordan","cite":"415 U.S. 651","y":1974,"id":"1973/72-1410","sc":1,"sum":"The Eleventh Amendment of the Constitution bars that portion of the District Court's decree that ordered retroactive pavment of benefits.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27","3":"15"}},{"t":"case","label":"Edwards v. Beck","cite":"786 F.3d 1113","y":2015,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/786/1113/","by":{"0":"5"}},{"t":"case","label":"EEOC v. Abercrombie & Fitch Stores, Inc.","cite":"575 U.S. 768","y":2015,"id":"2014/14-86","sc":1,"sum":"The Court held that an employer may be held liable under Title VII of the Civil Rights Act if an applicant can show that her need for an accommodation was a motivating factor in the employer’s decision not to hire her.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Finberg v. Sullivan","cite":"634 F.2d 50","y":1980,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/634/50/","sum":"Finding plaintiff’s injury traceable to a clerk and sheriff because performance of their ministerial duties in post-judgment garnishment proceedings was “the immediate cause[]” of plaintiff’s injury.","sumSrc":"brief:3","by":{"0":"30","3":"19"}},{"t":"case","label":"Fitzgerald v. Barnstable Sch. Comm.","cite":"555 U.S. 246","y":2009,"id":"2008/07-1125","sc":1,"sum":"The Court found that a claim filed under Title IX for violation of the Equal Protection Clause of the fourteenth Amendment does not preclude the use of 42 U.S.C. Section 1983 which protects against the deprivation of any rights guaranteed by the Constitution and federal law.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Gilmore v. City of Montgomery","cite":"417 U.S. 556","y":1974,"id":"1973/72-1517","sc":1,"sum":"Petitioners, Negro citizens of Montgomery, Ala., brought this class action in 1958 to desegregate the city's public parks, and in 1959 the District Court ordered the parks desegregated. The Court of Appeals affirmed, and ordered the District Court to retain jurisdiction. Thereafter, however, segregated recreational programs were continued by the city in cooperation with the YMCA, public swimming pools were closed …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"Green v. Mansour","cite":"474 U.S. 64","y":1985,"id":"1985/84-6270","sc":1,"sum":"Petitioner recipients of benefits under the federal Aid to Families With Dependent Children (AFDC) program brought class actions in Federal District Court against respondent Director of the Michigan Department of Social Services. They claimed that respondent's policies of prohibiting the deduction of child care costs and requiring the inclusion of stepparents' income for purposes of calculating earned income, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Guam Soc’y of Obstetricians & Gynecologists v. Ada","cite":"962 F.2d 1366","y":1992,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/962/1366/","by":{"0":"5"}},{"t":"case","label":"Idaho v. Coeur d’Alene Tribe of Idaho","cite":"521 U.S. 261","y":1997,"id":"1996/94-1474","sc":1,"sum":"Authored by Justice Anthony Kennedy, the Court ruled that the Coeur d'Alene Tribe's suit against the state officials may not proceed in federal court because States enjoy Eleventh Amendment immunity in suits filed by Indian tribes.","sumSrc":"Oyez","by":{"0":"27, 38","1":"41, 44","2":"27","3":"14"}},{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"sum":"The Court held that the Immigration and Nationality Act violated the separation of powers by allowing a one-house veto over executive decisions.","sumSrc":"Oyez","by":{"0":"43, 44","3":"8"}},{"t":"case","label":"Isaacson v. Horne","cite":"716 F.3d 1213","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/716/1213/","by":{"0":"5"}},{"t":"case","label":"Jane L. v. Bangerter","cite":"102 F.3d 1112","y":1996,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/102/1112/","by":{"0":"5"}},{"t":"case","label":"June Med. Servs. L.L.C. v. Russo","cite":"140 S. Ct. 2103","y":2020,"id":"2019/18-1323","sc":1,"op":2,"ar":1,"sum":"A case in which the Court reversed a decision by the U.S. Court of Appeals for the Fifth Circuit upholding Louisiana’s law requiring physicians who perform abortions to have admitting privileges at a local hospital because it conflicted with the Court’s binding precedent in Whole Woman’s Health v. Hellerstedt.","sumSrc":"Oyez","by":{"0":"3, 5"}},{"t":"case","label":"Kallinen v. City of Houston","cite":"462 S.W.3d 25","y":2015,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.3d/462/25/","by":{"0":"34"}},{"t":"case","label":"Kitchen v. Herbert","cite":"755 F.3d 1193","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/755/1193/","sum":"Holding that a clerk responsible for issuing marriage licenses was a proper defendant in a suit challenging a same-sex-marriage ban.","sumSrc":"brief:3","by":{"0":"30","3":"19"}},{"t":"case","label":"Kungys v. United States","cite":"485 U.S. 759","y":1988,"id":"1986/86-228","sc":1,"sum":"The judgment of the Court of Appeals is reversed, and the case is remanded. 793 F. 2d 516, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34"}},{"t":"case","label":"Lugar v. Edmondson Oil Co.","cite":"457 U.S. 922","y":1982,"id":"1981/80-1730","sc":1,"sum":"Section 1983 offers relief to those who have their rights unlawfully abridged by actions occurring \"under the color of state law.\" The Court decided that a state was liable for damages caused by unconstitutional conduct when two conditions were met.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Lynch v. Household Fin. Corp.","cite":"405 U.S. 538","y":1972,"id":"1971/70-5058","sc":1,"sum":"Appellee Household Finance Corp. sued appellant Lynch in state court alleging nonpayment of a promissory note, and, prior to serving her with process, garnished her savings account under Connecticut law authorizing summary pre-judicial garnishment. Appellant challenged the validity of the state statutes under the Equal Protection and Due Process Clauses of the Fourteenth Amendment, and sought declaratory and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"McCormack v. Herzog","cite":"788 F.3d 1017","y":2015,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/788/1017/","by":{"0":"5"}},{"t":"case","label":"MedImmune, Inc. v. Genentech, Inc.","cite":"549 U.S. 118","y":2007,"id":"2006/05-608","sc":1,"sum":"The Court reversed the Federal Circuit and ruled for MedImmune.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Mireles v. Waco","cite":"502 U.S. 9","y":1991,"id":"1991/91-311","sc":1,"sum":"The Court of Appeals erred in ruling that Judge Mireles' alleged actions were not taken in his judicial capacity. Judicial immunity is an immunity from suit, not just from ultimate assessment of damages, and it can be overcome only if a judge's actions are nonjudicial or were taken in the complete absence of all jurisdiction. Here, the judge's function of directing police officers to bring counsel in a pending case …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32","1":"32"}},{"t":"case","label":"Mitchell v. Robert DeMario Jewelry, Inc.","cite":"361 U.S. 288","y":1960,"id":"1959/39","sc":1,"sum":"In an action by the Secretary of Labor under § 17 of the Fair Labor Standards Act of 1938, as amended, to restrain violations of § 15 (a) (3), a district court has jurisdiction to order an employer to reimburse employees unlawfully discharged or otherwise discriminated against for wages lost because of that discharge or discrimination.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33"}},{"t":"case","label":"Mitchum v. Foster","cite":"407 U.S. 225","y":1972,"id":"1971/70-27","sc":1,"op":4,"ar":1,"sum":"Title 42 U. S. C.'§ 1983, which authorizes a suit in-equity to redress the deprivation under color of state law \"of any rights, privileges, or immunities secured by theConstitution.. '.,\" is within that exception of the federal anti-injunction statute, 28 U. S. C. § 2283, that provides 'that a federal court may not enjoin state court proceedings \"except as. expressly authorized by Act of Congress.\" And in this § …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22, 23, 24, 33","3":"15"}},{"t":"case","label":"MKB Mgmt. Corp. v. Stenehjem","cite":"795 F.3d 768","y":2015,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/795/768/","by":{"0":"5"}},{"t":"case","label":"Monell v. Dep’t of Soc. Servs.","cite":"436 U.S. 658","y":1978,"id":"1977/75-1914","sc":1,"sum":"The Court held that the legislative history of the Civil Rights Act of 1871, and specifically the Sherman Amendment, indicated that municipalities could be liable for the infringement of constitutional rights. Additionally, by 1871 there was a clear legislative and precedent-based history for municipal corporations — such as a school board — to be considered a “person” for the purpose of lawsuits and liability.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Monroe v. Pape","cite":"365 U.S. 167","y":1961,"id":"1960/39","sc":1,"sum":"Yes and No. Justice William O. Douglas, writing for the majority, stated that the city police officers, in conducting an unreasonable search and seizure, had committed an action which was under the color of law, and that the police could be held liable individually under the Civil Rights Act. However, the majority further held that a municipality could not be liable under the Civil Rights Act.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"New Hampshire v. Maine","cite":"532 U.S. 742","y":2001,"id":"2000/130_orig","sc":1,"sum":"The Court held that \"judicial estoppel bars New Hampshire from asserting that the Piscataqua River boundary runs along the Maine shore.\" Under the judicial estoppel doctrine, \"[w]here a party assumes a certain position in a legal proceeding, and succeeds in maintaining that position, he may not thereafter, simply because his interests have changed, assume a contrary position, especially if it be to the prejudice of the party who has acquiesced in the position formerly taken by him,\" wrote Justice Ginsburg. \"New Hampshire's claim that the Piscataqua River boundary runs along the Maine shore is clearly inconsistent with its interpretation of the words 'Middle of the River' during the 1970's litigation,\" concluded Ginsburg.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Obergefell v. Hodges","cite":"576 U.S. 644","y":2015,"id":"2014/14-556","sc":1,"sum":"The Court held that the Fourteenth Amendment requires states to license and recognize same-sex marriage.","sumSrc":"Oyez","by":{"0":"49","3":"13"}},{"t":"case","label":"P.R. Aqueduct & Sewer Auth. v. Metcalf & Eddy, Inc.","cite":"506 U.S. 139","y":1993,"id":"1992/91-1010","sc":1,"sum":"States and state entities that claim to be \"arms of the State\" may take advantage of the collateral order doctrine of Cohen v. Beneficial Industrial Loan Corp., 337 U. S. 541, to appeal a district court order denying a claim of Eleventh Amendment immunity from suit in federal court. Although 28 U. S. C. § 1291 requires that appeals be taken from \"final decisions of the district courts,\" Cohen, supra, at 546, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2","1":"4","2":"11"}},{"t":"case","label":"Patsy v. Bd. of Regents of Fla.","cite":"457 U.S. 496","y":1982,"id":"1981/80-1874","sc":1,"sum":"Exhaustion of state administrative remedies is not a prerequisite to an action under § 1983.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Perez v. Ledesma","cite":"401 U.S. 82","y":1971,"id":"1970/60","sc":1,"op":1,"sum":"The Supreme Court held that the district court’s ruling on the validity of the arrests and seizure constituted improper federal interference with state criminal proceedings. The Court reversed that judgment. The Court also held that it had no jurisdiction to review the order declaring the ordinance invalid on direct appeal. Justice Potter Stewart concurred, citing several cases in support of his decision.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Planned Parenthood of Se. Pa. v. Casey","cite":"505 U.S. 833","y":1992,"id":"1991/91-744","sc":1,"op":3,"sum":"A case in which the Court introduced a new standard of determining the validity of abortion laws by asking if the restrictions place any \"undue burden\" on the mother attempting to abort the fetus. If the restriction is found to do so, it is invalid.","sumSrc":"Oyez","by":{"0":"5","1":"31"}},{"t":"case","label":"Plyler v. Doe","cite":"457 U.S. 202","y":1982,"id":"1981/80-1538","sc":1,"sum":"The Court found that it was unconstitutional for the State to withhold funds from school districts educating children of illegal aliens.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Pulliam v. Allen","cite":"466 U.S. 522","y":1984,"id":"1983/82-1432","sc":1,"op":2,"ar":1,"sum":"The Court held that the precedent set by British common law relied on the issuance of writs, rather than the imposition of judicial immunity, to protect judicial independence. The United States never had a doctrine of judicial immunity from prospective relief, and there was no evidence that the lack of that protection created a chilling effect on judicial independence.","sumSrc":"Oyez","by":{"0":"22, 32, 42","2":"26"}},{"t":"case","label":"Reitman v. Mulkey","cite":"387 U.S. 369","y":1967,"id":"1966/483","sc":1,"sum":"The California Supreme Court believes that Art. I, § 26, which does not merely repeal existing law forbidding private racial discrimination but authorizes racial discrimination in the housing market and establishes the right to discriminate as a basic state policy, will significantly encourage and involve the State in private discriminations. No persuasive considerations indicating that the judgments herein should …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"Roe v. Wade","cite":"410 U.S. 113","y":1973,"id":"1971/70-18","sc":1,"op":2,"sum":"A case in which the Court struck down several Texas laws that criminalized abortion, holding that laws that impose an undue burden on a woman’s right to seek an abortion violate her fundamental right to privacy under the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"3, 45","3":"8"}},{"t":"case","label":"Shelley v. Kraemer","cite":"334 U.S. 1","y":1948,"id":"1940-1955/334us1","sc":1,"op":2,"ar":2,"sum":"The Court ruled that enforcement of racially restrictive covenants were a violation of the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Sojourner T v. Edwards","cite":"974 F.2d 27","y":1992,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/974/27/","by":{"0":"5"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"0":"44","3":"20"}},{"t":"case","label":"Steffel v. Thompson","cite":"415 U.S. 452","y":1974,"id":"1973/72-5581","sc":1,"sum":"The Court held that the case presented an actual controversy, as the Georgia statute could interfere with Steffel’s exercise of his constitutional rights even if he was not arrested. Because the United States’ involvement in Vietnam, which Steffel was protesting, was reduced, the issue of whether or not the case still presented an active controversy would be decided by the lower court on remand.","sumSrc":"Oyez","by":{"0":"24, 25, 40","2":"29, 34","3":"21"}},{"t":"case","label":"Strickland v. Alexander","cite":"772 F.3d 876","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/772/876/","sum":"Finding traceability satisfied where a plaintiff sued a clerk to prevent the filing of a garnishment affidavit and summons, although garnishment proceedings could only be initiated by creditors not before the court.","sumSrc":"brief:3","by":{"0":"22, 30","3":"19"}},{"t":"case","label":"Sup. Ct. of Va. v. Consumers Union of U.S., Inc.","cite":"446 U.S. 719","y":1980,"id":"1979/79-198","sc":1,"sum":"The Court held that the Supreme Court of Virginia was immune to suits in its legislative capacity, just as any other legislative body would be. However, the Supreme Court of Virginia has the power to enforce the Code, and this suit was brought against it in its enforcement capacity.","sumSrc":"Oyez","by":{"0":"33","2":"26"}},{"t":"case","label":"Susan B. Anthony List v. Driehaus","cite":"573 U.S. 149","y":2014,"id":"2013/13-193","sc":1,"op":1,"sum":"The Court held that pre-enforcement challenges are justiciable when evidence indicates that threatened enforcement of the law is sufficiently imminent.","sumSrc":"Oyez","by":{"0":"24, 39, 40","3":"18, 19"}},{"t":"case","label":"Tandon v. Newsom","cite":"141 S. Ct. 1294","y":2021,"url":"https://www.courtlistener.com/c/S.%20Ct./141/1294/","sc":1,"sum":"Recognizing that S.B. 8’s delegation “to the populace at large” is designed “to insulate the State from responsibility for implementing and enforcing the regulatory regime”.","sumSrc":"brief:0","by":{"0":"49"}},{"t":"case","label":"Terry v. Adams","cite":"345 U.S. 461","y":1953,"id":"scdb/1952-084","sc":1,"sum":"For opinion of MR. Justice Black, joined by Mr. Justice Douglas and Mr. Justice Burton, see post, p. 462.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"Texas v. Johnson","cite":"491 U.S. 397","y":1989,"id":"1988/88-155","sc":1,"sum":"The Court held that burning the American Flag is protected free speech under the First Amendment.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Thermo Prods. Co. v. Chilton Indep. Sch. Dist.","cite":"647 S.W.2d 726","y":1983,"court":"Tex. App.","url":"https://www.courtlistener.com/c/S.W.2d/647/726/","by":{"0":"35"}},{"t":"case","label":"United States v. Texas","cite":"2021 WL 4593319","y":2021,"court":"W.D. Tex. Oct. 6","by":{"0":"passim","3":"20"}},{"t":"case","label":"United States v. Windsor","cite":"570 U.S. 744","y":2013,"id":"2012/12-307","sc":1,"sum":"The Court found that the Defense of Marriage Act (DOMA) was unconstitutional under the equal protection clause of the Fifth Amendment.","sumSrc":"Oyez","by":{"0":"43, 44, 45"}},{"t":"case","label":"Va. Off. for Prot. & Advoc. v. Stewart","cite":"563 U.S. 247","y":2011,"id":"2010/09-529","sc":1,"op":3,"sum":"The Court held that a federal court may hear a lawsuit for prospective injunctive relief against state officials brought by another agency of the same state.","sumSrc":"Oyez","by":{"0":"25, 26, 27, 28","3":"13, 15"}},{"t":"case","label":"Verizon Md., Inc. v. Pub. Serv. Comm’n of Md.","cite":"535 U.S. 635","y":2002,"id":"2001/00-1531","sc":1,"sum":"The Court held that the district court had jurisdiction, so as to review the Commission's order for compliance with federal law, to entertain the suit because resolution of the LEC's claim turned on whether the Act, or an FCC ruling issued thereunder, precluded the state commission from ordering payment of reciprocal compensation.","sumSrc":"Oyez","by":{"0":"27, 31"}},{"t":"case","label":"Virginia v. Am. Booksellers Ass’n","cite":"484 U.S. 383","y":1988,"id":"1987/86-1034","sc":1,"sum":"A 1985 amendment to a Virginia statute makes it unlawful for any person \"to knowingly display for commercial purposes in a manner whereby juveniles may examine and peruse\" certain visual or written sexual or sadomasochistic material that is harmful to juveniles. What is \"harmful to juveniles\" is defined elsewhere in the statute. Plaintiffs, a number of booksellers' organizations and two Virginia non-\"adults only,\" …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Women’s Med. Pro. Corp. v. Voinovich","cite":"130 F.3d 187","y":1997,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/130/187/","by":{"0":"5"}},{"t":"case","label":"Younger v. Harris","cite":"401 U.S. 37","y":1971,"id":"1970/2","sc":1,"op":2,"sum":"In an 8-to-1 decision, the Court held that \"settled doctrines\" of federalism narrowly confined the availability of injunctive relief against state criminal prosecutions.","sumSrc":"Oyez","by":{"0":"33","3":"15, 16"}},{"t":"usc","label":"18 U.S.C. § 3156","url":"https://www.law.cornell.edu/uscode/text/18/3156","subs":["(a)(1)"],"by":{"0":"22"}},{"t":"usc","label":"18 U.S.C. § 3172","url":"https://www.law.cornell.edu/uscode/text/18/3172","subs":["(1)"],"by":{"0":"22"}},{"t":"usc","label":"28 U.S.C. § 480","url":"https://www.law.cornell.edu/uscode/text/28/480","by":{"0":"22"}},{"t":"usc","label":"28 U.S.C. § 482","url":"https://www.law.cornell.edu/uscode/text/28/482","by":{"0":"22"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"stext":{"head":"§1254. Courts of appeals; certiorari; certified questions","paras":[[0,"Cases in the courts of appeals may be reviewed by the Supreme Court by the following methods:"],[1,"(1) By writ of certiorari granted upon the petition of any party to any civil or criminal case, before or after rendition of judgment or decree;"],[1,"(2) By certification at any time by a court of appeals of any question of law in any civil or criminal case as to which instructions are desired, and upon such certification the Supreme Court may give binding instructions or require the entire record to be sent up for decision of the entire matter in controversy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1254?type=usc&year=mostrecent&link-type=html"},"head":"§1254. Courts of appeals; certiorari; certified questions","tname":"Judiciary and Judicial Procedure","by":{"0":"4","1":"4"}},{"t":"usc","label":"28 U.S.C. § 1827","url":"https://www.law.cornell.edu/uscode/text/28/1827","by":{"0":"22"}},{"t":"usc","label":"28 U.S.C. § 2101","url":"https://www.law.cornell.edu/uscode/text/28/2101","by":{"0":"4, 25"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":5,"head":"§1983. Civil action for deprivation of rights","tname":"The Public Health and Welfare","by":{"0":"passim","1":"passim","2":"passim","3":"1, 13"}},{"t":"usc","label":"42 U.S.C. § 1988","url":"https://www.law.cornell.edu/uscode/text/42/1988","subs":["(b)"],"stext":{"head":"§1988. Proceedings in vindication of civil rights","paras":[[0,"(a) Applicability of statutory and common law"],[0,"The jurisdiction in civil and criminal matters conferred on the district courts by the provisions of titles 13, 24, and 70 of the Revised Statutes for the protection of all persons in the United States in their civil rights, and for their vindication, shall be exercised and enforced in conformity with the laws of the United States, so far as such laws are suitable to carry the same into effect; but in all cases where they are not adapted to the object, or are deficient in the provisions necessary to furnish suitable remedies and punish offenses against law, the common law, as modified and changed by the constitution and statutes of the State wherein the court having jurisdiction of such civil or criminal cause is held, so far as the same is not inconsistent with the Constitution and laws of the United States, shall be extended to and govern the said courts in the trial and disposition of the cause, and, if it is of a criminal nature, in the infliction of punishment on the party found guilty."],[0,"(b) Attorney's fees"],[0,"In any action or proceeding to enforce a provision of sections 1981, 1981a, 1982, 1983, 1985, and 1986 of this title, title IX of Public Law 92–318 [20 U.S.C. 1681 et seq.], the Religious Freedom Restoration Act of 1993 [42 U.S.C. 2000bb et seq.], the Religious Land Use and Institutionalized Persons Act of 2000 [42 U.S.C. 2000cc et seq.], title VI of the Civil Rights Act of 1964 [42 U.S.C. 2000d et seq.], or section 12361 of title 34, the court, in its discretion, may allow the prevailing party, other than the United States, a reasonable attorney's fee as part of the costs, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity such officer shall not be held liable for any costs, including attorney's fees, unless such action was clearly in excess of such officer's jurisdiction."],[0,"(c) Expert fees"],[0,"In awarding an attorney's fee under subsection (b) in any action or proceeding to enforce a provision of section 1981 or 1981a of this title, the court, in its discretion, may include expert fees as part of the attorney's fee."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1988?type=usc&year=mostrecent&link-type=html"},"head":"§1988. Proceedings in vindication of civil rights","tname":"The Public Health and Welfare","by":{"0":"23","2":"45, 46"}},{"t":"law","label":"Pub. L. No. 104-317","url":"https://www.govinfo.gov/link/plaw/104/public/317","by":{"0":"22"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"0":"2, 11, 19, 24, 27, 38, 46"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"0":"20, 39, 41, 44"}},{"t":"case","label":"Adams v. McIlhany","cite":"764 F.2d 294","y":1985,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/764/294/","by":{"1":"34-35"}},{"t":"case","label":"Allen v. DeBello","cite":"861 F.3d 433","y":2017,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/861/433/","sum":"Holding state judges are not proper parties to a § 1983 suit challenging the constitutionality of state cus- tody dispute procedures because the judges could not initiate the actions themselves, had no administrative function under the statute, and did not promulgate the procedures.","sumSrc":"brief:1","by":{"1":"22","2":"5, 30"}},{"t":"case","label":"Bauer v. Texas","cite":"341 F.3d 352","y":2003,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/341/352/","by":{"1":"passim","2":"5, 23, 29"}},{"t":"case","label":"Broadrick v. Oklahoma","cite":"413 U.S. 601","y":1973,"id":"1972/71-1639","sc":1,"sum":"Section 818 of the Oklahoma statute is not unconstitutional on its face. CSC v. Letter Carriers, ante, p. 548.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"3","2":"49"}},{"t":"case","label":"Calderon v. Ashmus","cite":"523 U.S. 740","y":1998,"id":"1997/97-391","sc":1,"sum":"The Court held that \"this action for a declaratory judgment and injunctive relief is not a justiciable case within the meaning of Article III.\" \"If the class members file habeas petitions, and the State asserts Chapter 154, the members obviously can litigate California's compliance with Chapter 154 at that time.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"California v. Texas","cite":"141 S. Ct. 2104","y":2021,"id":"2020/19-840","sc":1,"op":1,"sum":"Plaintiffs lack standing to challenge the Patient Protection and Affordable Care Act’s minimum essential coverage provision.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"16, 35","2":"38, 39"}},{"t":"case","label":"Chicago & Grand Trunk R. Co. v. Wellman","cite":"143 U.S. 339","y":1892,"id":"scdb/1891-121","sc":1,"sum":"The act of the legislature of Michigan of June 28, 1889, (Public Laws of 1889, pp. 282, 283,) fixing the amount per mile to be charged by railways for the transportation of a passenger, violates noprovision in the Constitution of the United States, so far as disclosed by the facts in this case. A legislature has power to fix rates for the transportation of passengers by railways, arid the extent of judicial …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"City of Houston v. Swindall","cite":"960 S.W.2d 413","url":"https://www.courtlistener.com/c/S.W.2d/960/413/","by":{"1":"25"}},{"t":"case","label":"City of Los Angeles v. Lyons","cite":"461 U.S. 95","y":1983,"id":"1982/81-1064","sc":1,"sum":"In a 5-to-4 decision, the Court held that federal courts were without jurisdiction to entertain Lyons' claim for injunctive relief.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Clapper v. Amnesty Int’l","cite":"568 U.S. 398","y":2013,"id":"2012/11-1025","sc":1,"op":1,"sum":"The Court held that the respondents lacked Article III standing against FISA because fear of intercepted communication and costs incurred to avoid intercepted communications are not injuries.","sumSrc":"Oyez","by":{"1":"16, 33, 35","2":"22, 42, 45, 47","3":"20"}},{"t":"case","label":"Fitts v. McGhee","cite":"172 U.S. 516","y":1899,"id":"scdb/1898-054","sc":1,"sum":"A suit brought by the receivers of a railroad against the Attorney General of the State of Alabama and the Solicitor of the Eleventh Judicial Circuit of that State, to restrain them, as officers of the State, from taking steps to enforce against the complainants the provisions of a law of that State reducing the tolls which had been exacted of the public under a prior law for crossing on a bridge of the railroad …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"2, 42","3":"12"}},{"t":"case","label":"Fla. Businessmen for Free Enterprise v. City of Hollywood","cite":"648 F.2d 956","y":1981,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/648/956/","by":{"1":"16"}},{"t":"case","label":"Grant v. Johnson","cite":"15 F.3d 146","y":1994,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/15/146/","sum":"Holding that “judges adjudicating cases pursuant to state statutes may not be sued under § 1983 in a suit challenging the state law”.","sumSrc":"brief:1","by":{"1":"23"}},{"t":"case","label":"Griggs v. Provident Consumer Discount Co.","cite":"459 U.S. 56","y":1982,"id":"1982/82-5082","sc":1,"sum":"The Court of Appeals' analysis of Rule 4(a)(4) is contrary to the language and purposes of the 1979 amendments to the Rules of Appellate Procedure. Prior to 1979, if a notice of appeal was fied pending disposition of a motion to vacate, alter, or amend the judgment it was generally held that the district court retained jurisdiction to decide the motion and the notice of appeal was adequate for purposes of beginning …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13","2":"14"}},{"t":"case","label":"Hope Clinic v. Ryan","cite":"249 F.3d 603","y":2001,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/249/603/","by":{"1":"36, 37, 38","2":"4, 10"}},{"t":"case","label":"Hosanna-Tabor Evangelical Lutheran Church & Sch. v. Equal Emp. Opportunity Comm’n","cite":"565 U.S. 171","y":2012,"id":"2011/10-553","sc":1,"sum":"The Court found that a woman employed by a religious school who taught daily religion classes, was a commissioned minister, and regularly lead students in prayer and worship, did not have grounds to sue the school under the Ministerial Exception.","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"Just. Network Inc. v. Craighead Cty.","cite":"931 F.3d 753","y":2019,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/931/753/","op":1,"ar":3,"sum":"Holding “judicial immunity typically bars claims for prospective injunctive relief against judicial officials acting in their judicial capacity”.","sumSrc":"brief:1","by":{"1":"22"}},{"t":"case","label":"K.P. v. LeBlanc","cite":"729 F.3d 427","y":2013,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/729/427/","by":{"1":"36, 37"}},{"t":"case","label":"(VII) Cases—Continued: Kentucky v. Graham","cite":"473 U.S. 159","y":1985,"id":"1984/84-849","sc":1,"sum":"Section 1988 does not allow attorney's fees to be recovered from a governmental entity when a plaintiff sues governmental employees only in their personal capacities and prevails; accordingly, since this case was necessarily litigated as a personal-capacity and not as an officialcapacity action, it was error to award fees against the Commonwealth.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"40-41","2":"27"}},{"t":"case","label":"Kokkonen v. Guardian Life Ins. Co. of Am.","cite":"511 U.S. 375","y":1994,"id":"1993/93-263","sc":1,"sum":"A federal district court, possessing only that power authorized by Constitution and statute, lacks jurisdiction over a claim for breach of a contract, part of the consideration for which was dismissal of an earlier federal suit. No federal statute makes that connection (if it constitutionally could) the basis for federal-court jurisdiction over the contract dispute. Moreover, the doctrine of ancillary jurisdiction …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"Lance v. Coffman","cite":"549 U.S. 437","y":2007,"id":"2006/06-641","sc":1,"sum":"The Court determined that an individual citizen with no personal stake in litigation regarding the Election Clause of Article I cannot sue in federal court.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Lujan v. Defs. of Wildlife","cite":"504 U.S. 555","y":1992,"id":"1991/90-1424","sc":1,"sum":"Even if the Court were to assume that the agency-funded projects at issue threatened listed species, there was no proof that these actions would produce \"actual or imminent\" injuries to particular respondents who might some day wish to visit the foreign countries in question.","sumSrc":"Oyez","by":{"1":"21, 34","2":"passim"}},{"t":"case","label":"Masterpiece Cakeshop, Ltd., v. Colo. Civil Rights Comm’n","cite":"138 S. Ct. 1719","y":2018,"id":"2017/16-111","sc":1,"ar":1,"sum":"The Court held that the Colorado Civil Rights Commission's conduct in evaluating a cake shop owner's reasons for declining to make a wedding cake for a same-sex couple violated the Free Exercise Clause.","sumSrc":"Oyez","by":{"1":"44","2":"8"}},{"t":"case","label":"McClellon v. Lone Star Gas Co.","cite":"66 F.3d 98","y":1995,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/66/98/","by":{"1":"25"}},{"t":"case","label":"Mendez v. Heller","cite":"530 F.2d 457","y":1976,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/530/457/","sum":"Finding state court judges and clerks joined as defendants in a suit challenging New York’s durational residency requirement for divorce lack the requisite interest in defending the allegedly unconstitutional statutes.","sumSrc":"brief:1","by":{"1":"23, 25, 31, 32","2":"30"}},{"t":"case","label":"Nollet v. Justices of Trial Ct. of Com. of Mass.","cite":"248 F.3d 1127","y":2000,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/248/1127/","by":{"1":"32"}},{"t":"case","label":"Nova Health Sys. v. Gandy","cite":"416 F.3d 1149","y":2005,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/416/1149/","by":{"1":"36, 38, 39"}},{"t":"case","label":"O’ Shea v. Littleton","cite":"414 U.S. 488","y":1974,"id":"1973/72-953","sc":1,"sum":"Respondents, 17 black and two white residents of Cairo, Illinois, brought a civil rights class action against petitioners, a magistrate and a circuit court jfidge, who allegedly engaged under'color of state law, in a continuing pattern and practice of conduct consisting of illegal bond-setting, sentencing, and jury-fee practices in criminal cases, which assertedly deprived respondents and members of their class of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"34","2":"46"}},{"t":"case","label":"(VIII) Cases—Continued: Okpalobi v. Foster","cite":"244 F.3d 405","y":2001,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/244/405/","by":{"1":"36, 37, 38, 39, 40","2":"4, 10"}},{"t":"case","label":"Our Lady of Guadalupe Sch. v. MorrisseyBerru","cite":"140 S. Ct. 2049","y":2020,"id":"2019/19-267","sc":1,"sum":"The Court held that the First Amendment’s religion clauses prevent civil courts from adjudicating employment-discrimination claims brought by an employee against her religious employer, when the employee carried out important religious functions.","sumSrc":"Oyez","by":{"1":"43-44"}},{"t":"case","label":"Papasan v. Allain","cite":"478 U.S. 265","y":1986,"id":"1985/85-499","sc":1,"sum":"Federal school land grants to Mississippi in the early 19th century did not apply to lands in northern Mississippi that were held by the Chickasaw Indian Nation, an area that came to be the northern 23 counties in the State. The Chickasaws thereafter ceded this area to the United States by a treaty under which the lands were sold, but no lands for public schools (Sixteenth Section lands) were reserved from sale. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43"}},{"t":"case","label":"Pennhurst State Sch. & Hosp. v. Halderman","cite":"465 U.S. 89","y":1984,"id":"1982/81-2101","sc":1,"op":1,"sum":"The Eleventh Amendment prohibited the District Court from ordering state officials to conform their conduct to state law.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"40, 44","2":"6, 28"}},{"t":"case","label":"Poe v. Ullman","cite":"367 U.S. 497","y":1961,"id":"1960/60","sc":1,"sum":"The Court held that the ripeness doctrine prevents bringing claims to challenge criminal statutes that are not enforced.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Raines v. Byrd","cite":"521 U.S. 811","y":1997,"id":"1996/96-1671","sc":1,"sum":"In a 7-to-2 decision, which avoided the question of the Act's constitutionality, the Court held that the individual congressmen lacked proper Article III standing to maintain their suit. The Court explained that the congressmen failed to show how the allegedly unconstitutional Act resulted in their personal injury, since it applied to the entire institution of Congress.","sumSrc":"Oyez","by":{"1":"2","2":"50"}},{"t":"case","label":"Soc’y of Separationists, Inc. v. Herman","cite":"959 F.2d 1283","y":1992,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/959/1283/","by":{"1":"34"}},{"t":"case","label":"Spokeo, Inc. v. Robins","cite":"136 S. Ct. 1540","y":2016,"id":"2015/13-1339","sc":1,"sum":"The Court held that lower courts need to consider the elements of Article III standing analysis separately in determining whether standing is sufficient for a federal court to hear the case.","sumSrc":"Oyez","by":{"1":"2, 35","2":"passim"}},{"t":"case","label":"Stone v. Powell","cite":"428 U.S. 465","y":1976,"id":"1975/74-1055","sc":1,"ar":7,"sum":"In a 6-to-3 decision, the Court held that where states had provided opportunities for full and fair litigation of Fourth Amendment claims, the Constitution did not require the granting of federal habeas corpus relief. The Court also held that any additional benefits from considering search and seizure claims of state prisoners on collateral review would be small in relation to the costs.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Summit Med. Assocs., P.C. v. Pryor","cite":"180 F.3d 1326","y":1999,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/180/1326/","by":{"1":"43","2":"4, 10"}},{"t":"case","label":"(IX) Cases—Continued: Thompson v. Coleman","cite":"2002 WL 1340314","by":{"1":"25"}},{"t":"case","label":"Uzuegbunam v. Preczewski","cite":"141 S. Ct. 792","y":2021,"id":"2020/19-968","sc":1,"sum":"A request for nominal damages satisfies the redressability element necessary for Article III standing where a plaintiff’s claim is based on a completed violation of a legal right.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"1, 22"}},{"t":"case","label":"Whitmore v. Arkansas","cite":"495 U.S. 149","y":1990,"id":"1989/88-7146","sc":1,"sum":"Whitmore lacks standing to proceed in this Court.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33, 35","2":"42, 45, 46, 47"}},{"t":"case","label":"Whole Woman’s Health v. Jackson","cite":"13 F.4th 434","y":2021,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/13/434/","by":{"1":"passim","2":"passim"}},{"t":"case","label":"Williams v. Brooks","cite":"996 F.2d 728","y":1993,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/996/728/","by":{"1":"14","2":"15"}},{"t":"const","label":"Article III, Section 2","clauses":[["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"]],"text":"The judicial Power shall extend to all Cases, in Law and Equity, arising under this Constitution, the Laws of the United States, and Treaties made, or which shall be made, under their Authority;—to all Cases affecting Ambassadors, other public Ministers and Consuls;—to all Cases of admiralty and maritime Jurisdiction;—to Controversies to which the United States shall be a Party;—to Controversies between two or more States;— between a State and Citizens of another State,—between Citizens of different States,—between Citizens of the same State claiming Lands under Grants of different States, and between a State, or the Citizens thereof, and foreign States, Citizens or Subjects. In all Cases affecting Ambassadors, other public Ministers and Consuls, and those in which a State shall be Party, the supreme Court shall have original Jurisdiction. In all the other Cases before mentioned, the supreme Court shall have appellate Jurisdiction, both as to Law and Fact, with such Exceptions, and under such Regulations as the Congress shall make. The Trial of all Crimes, except in Cases of Impeachment, shall be by Jury; and such Trial shall be held in the State where the said Crimes shall have been committed; but when not committed within any State, the Trial shall be at such Place or Places as the Congress may by Law have directed.","by":{"1":"5, 21","2":"12"}},{"t":"const","label":"Amendment XI","clauses":[["eleventh-amendment","Eleventh Amendment"]],"text":"The Judicial power of the United States shall not be construed to extend to any suit in law or equity, commenced or prosecuted against one of the United States by Citizens of another State, or by Citizens or Subjects of any Foreign State.","by":{"1":"5"}},{"t":"const","label":"Amendment XIV, Section 5","clauses":[["enforcement-14","Enforcement Clause (Section 5)"]],"text":"The Congress shall have power to enforce, by appropriate legislation, the provisions of this article.","by":{"1":"3"}},{"t":"rule","label":"Fed. R. Civ. P. 4","url":"https://www.law.cornell.edu/rules/frcp/rule_4","by":{"1":"7"}},{"t":"case","label":"Aetna Life Insurance Co. v. Haworth","cite":"300 U.S. 227","y":1937,"id":"scdb/1936-068","sc":1,"sum":"1. The Federal Declaratory Judgment Act deals with \"controversies\" in the constitutional sense and is procedural only.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"23"}},{"t":"case","label":"Babb v. Wilkie","cite":"140 S. Ct. 1168","y":2020,"id":"2019/18-882","sc":1,"sum":"The Court held that the federal-sector provision of the Age Discrimination in Employment Act of 1967 demands that personnel actions be untainted by any consideration of age, but but-for causation is important in determining the appropriate remedy that may be obtained.","sumSrc":"Oyez","by":{"2":"3"}},{"t":"case","label":"Bostock v. Clayton County","cite":"140 S. Ct. 1731","y":2020,"id":"2019/17-1618","sc":1,"sum":"The Court held that Title VII of the Civil Rights Act of 1964, which prohibits against employment discrimination “because of . . . sex” encompasses discrimination based on an individual’s sexual orientation.","sumSrc":"Oyez","by":{"2":"2"}},{"t":"case","label":"Camreta v. Greene","cite":"563 U.S. 692","y":2011,"id":"2010/09-1454","sc":1,"op":1,"sum":"A case which the Court vacated in part and remanded in favor of the defendant without addressing the Fourth Amendment question at issue.","sumSrc":"Oyez","by":{"2":"43"}},{"t":"case","label":"Carmichael v. United Technologies Corp.","cite":"835 F.2d 109","y":1988,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/835/109/","by":{"2":"31"}},{"t":"case","label":"Carney v. Adams","cite":"141 S. Ct. 493","y":2020,"id":"2020/19-309","sc":1,"sum":"Because plaintiff Adams has not shown that he was “able and ready” to apply for a judicial vacancy in the imminent future, Gratz v. Bollinger, 539 U. S. 244, 262, he has failed to demonstrate Article III standing to challenge the Delaware Constitution’s political balance requirement for appointments to the State’s major courts.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"31"}},{"t":"case","label":"Christiansburg Garment Co. v. EEOC","cite":"434 U.S. 412","y":1978,"id":"1977/76-1383","sc":1,"sum":"Two years after a racial discrimination charge under Title VII of the Civil Rights Act of 1964 had been filed against petitioner company, respondent, the Equal Employment Opportunity Commission (EEOC), notified the complainant that its conciliation efforts had failed and that she had the right to sue the company, which she did not do. Almost two years later, § 14 of the 1972 amendments to Title VII authorized the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"46, 48"}},{"t":"case","label":"Clark v. Tarrant County","cite":"798 F.2d 736","y":1986,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/798/736/","sum":"Holding that district judges in Texas “are undeniably elected state officials” for purposes of state sovereign immunity.","sumSrc":"brief:2","by":{"2":"27"}},{"t":"case","label":"(vii) Commodity Trend Service, Inc. v. Commodity Futures Trading Comm’n","cite":"149 F.3d 679","y":1998,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/149/679/","by":{"2":"35"}},{"t":"case","label":"Davis v. Federal Election Comm’n","cite":"554 U.S. 724","y":2008,"id":"2007/07-320","sc":1,"sum":"Although all nine Justices agreed that Davis had standing to argue his case before the Court, only a 5-4 majority held that the contribution limits violated the First Amendment. In his majority opinion, Justice Samuel Alito noted that the Court had never upheld the constitutionality of a law imposing different contribution limits for candidates competing against one another.","sumSrc":"Oyez","by":{"2":"31"}},{"t":"case","label":"Digital Recognition Network, Inc. v. Hutchinson","cite":"803 F.3d 952","y":2015,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/803/952/","by":{"2":"4, 10"}},{"t":"case","label":"Gras v. Stevens","cite":"415 F. Supp. 1148","y":1976,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./415/1148/","by":{"2":"45"}},{"t":"case","label":"Hansberry v. Lee","cite":"311 U.S. 32","y":1940,"id":"scdb/1940-006","sc":1,"sum":"Numerous owners of lots in a particular area agreed in writing, each severally with each of the others, that their lots should not be sold to or occupied by Negroes, the effectiveness of the agreement being conditioned, however, upon signing by owners of a specified percentage of the lot frontage. In a case in a state court, tried upon an agreed statement of facts, in which it was stipulated (erroneously) that this …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"43"}},{"t":"case","label":"Harper v. Virginia Dep’t of Taxation","cite":"509 U.S. 86","y":1993,"id":"1992/91-794","sc":1,"sum":"In Davis v. Michigan Dept. of Treasury,489 U. S. 803, this Court invalidated Michigan's practice of taxing retirement benefits paid by the Federal Government while exempting retirement benefits paid by the State or its political subdivisions. Because Michigan conceded that a refund to federal retirees was the appropriate remedy, the Court remanded for entry of judgment against the State. Virginia subsequently …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"10"}},{"t":"case","label":"Hollis v. Itawamba County Loans","cite":"657 F.2d 746","y":1981,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/657/746/","by":{"2":"45"}},{"t":"case","label":"Howard Gault Co. v. Texas Rural Legal Aid, Inc.","cite":"848 F.2d 544","y":1988,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/848/544/","by":{"2":"45"}},{"t":"case","label":"Hustler Magazine, Inc. v. Falwell","cite":"485 U.S. 46","y":1988,"id":"1987/86-1278","sc":1,"sum":"The Court ruled that the First Amendment's freedom of speech protection extended to the making of clearly offensive statements about public figures, so long as such speech could not reasonably be construed to convey facts about its subject.","sumSrc":"Oyez","by":{"2":"1"}},{"t":"case","label":"International Longshoremen’s and Warehousemen’s Union, Local 37 v. Boyd","cite":"347 U.S. 222","y":1954,"id":"1940-1955/347us222","sc":1,"sum":"The complaint must be dismissed as not presenting a \"case or controversy\" appropriate for adjudication. Pp. 222-224. 111 F. Supp. 802, judgment vacated and cause remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"49"}},{"t":"case","label":"Maryland Casualty Co. v. Pacific Coal & Oil Co.","cite":"312 U.S. 270","y":1941,"id":"scdb/1940-168","sc":1,"sum":"MD. CASUALTY CO. v. PACIFIC CO.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"48"}},{"t":"case","label":"McCartney v. First City Bank","cite":"970 F.2d 45","y":1992,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/970/45/","by":{"2":"45"}},{"t":"case","label":"Menchaca v. Chrysler Credit Corp.","cite":"613 F.2d 507","y":1980,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/613/507/","by":{"2":"31"}},{"t":"case","label":"Middlesex County Ethics Commission v. Garden State Bar Ass’n","cite":"457 U.S. 423","y":1982,"id":"1981/81-460","sc":1,"sum":"The federal courts should abstain from interfering with the ongoing disciplinary proceedings within the jurisdiction of the New Jersey Supreme Court.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"6, 29"}},{"t":"case","label":"New York Times Co. v. Sullivan","cite":"376 U.S. 254","y":1964,"id":"1963/39","sc":1,"ar":3,"sum":"The Court held that the First Amendment protects freedom of speech and freedom of the press, even about the conduct of politicians, unless the statements are made with actual malice.","sumSrc":"Oyez","by":{"2":"1, 2, 8"}},{"t":"case","label":"(ix) Sheldon v. Sill","cite":"49 U.S. 441","y":1850,"id":"scdb/1850-030","sc":1,"ar":1,"sum":"Courts created by statute can have no jurisdiction but such as the statute confers.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"9"}},{"t":"case","label":"State v. Arlene’s Flowers, Inc.","cite":"441 P.3d 1203","y":2019,"court":"Wash.","url":"https://www.courtlistener.com/c/P.3d/441/1203/","by":{"2":"8"}},{"t":"case","label":"TransUnion LLC v. Ramirez","cite":"141 S. Ct. 2190","y":2021,"id":"2020/20-297","sc":1,"sum":"Only a plaintiff concretely harmed by a defendant’s violation of the Fair Credit Reporting Act has Article III standing to seek damages against that private defendant in federal court.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"31, 49","3":"17"}},{"t":"case","label":"Warth v. Seldin","cite":"42 U.S. 490","y":1975,"id":"1974/73-2024","sc":1,"sum":"Whether the rules of standing are considered as aspects of the constitutional requirement that a plaintiff must make out a \"case or controversy\" within the meaning of Art. III, or, apart from such requirement, as prudential limitations on the courts' role in resolving disputes involving \"generalized grievances\" or third parties' legal rights or interests, none of the petitioners has met the threshold requirement of …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"42, 45, 47","3":"20"}},{"t":"case","label":"Williamson v. Tucker","cite":"645 F.2d 404","y":1981,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/645/404/","by":{"2":"36"}},{"t":"usc","label":"15 U.S.C. § 7901","url":"https://www.law.cornell.edu/uscode/text/15/7901","by":{"2":"2"}},{"t":"usc","label":"18 U.S.C. § 1531","url":"https://www.law.cornell.edu/uscode/text/18/1531","by":{"2":"9"}},{"t":"usc","label":"28 U.S.C. § 1257","url":"https://www.law.cornell.edu/uscode/text/28/1257","by":{"2":"7"}},{"t":"law","label":"Pub. L. No. 108-105","url":"https://www.govinfo.gov/link/plaw/108/public/105","by":{"2":"9"}},{"t":"law","label":"Patient Protection and Affordable Care Act, Pub. L. No. 111-148","url":"https://www.govinfo.gov/link/plaw/111/public/148","by":{"2":"10"}},{"t":"law","label":"Protection of Lawful Commerce in Arms Act, Pub. L. No. 109-92","url":"https://www.govinfo.gov/link/plaw/109/public/92","by":{"2":"2"}},{"t":"law","label":"Pub. L. No. 103-141","url":"https://www.govinfo.gov/link/statute/107/1488","by":{"2":"2"}},{"t":"law","label":"Pub. L. No. 109-246","url":"https://www.govinfo.gov/link/plaw/109/public/246","by":{"2":"9"}},{"t":"case","label":"303 Creative LLC v. Elenis","cite":"6 F.4th 1160","y":2021,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/6/1160/","by":{"3":"9"}},{"t":"case","label":"Bennett v. Spear","cite":"520 U.S. 154","y":1997,"id":"1996/95-813","sc":1,"sum":"In the unanimous decision, announced by Justice Antonin Scalia, the Court ruled that the petitioners had standing to ask for judicial review of the minimum water level setting under the Endangered Species Act. The Act explicitly allows \"any person\" to sue the government over an alleged violation. Justice Scalia asserted this applies to the Secretary's actions over enforcement.","sumSrc":"Oyez","by":{"3":"19"}},{"t":"case","label":"Bowen v. Doyle","cite":"230 F.3d 525","y":2000,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/230/525/","by":{"3":"15"}},{"t":"case","label":"City of Houston v. Hill","cite":"482 U.S. 451","y":1987,"id":"1986/86-243","sc":1,"sum":"Upon shouting at police in an attempt to divert their attention from his friend during a confrontation, appellee was arrested for \"wilfully... interrupt[ing] a city policeman... by verbal challenge during an investigation\" in violation of a municipal ordinance making it unlawful for any person \"to assault, strike or in any manner oppose, molest, abuse or interrupt any policeman in the execution of his duty.\" After …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"11"}},{"t":"case","label":"DeBoer v. Snyder","cite":"772 F.3d 388","y":2014,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/772/388/","by":{"3":"13"}},{"t":"case","label":"Dennis v. Sparks","cite":"449 U.S. 24","y":1980,"id":"1980/79-1186","sc":1,"sum":"The action against the private parties accused of conspiring with the judge is not subject to dismissal. Private persons, jointly engaged with state officials in a challenged action, are acting \"under color\" of law for purposes of § 1983 actions. And the judge's immunity from damages liability for an official act that was allegedly the product of a corrupt conspiracy involving bribery of the judge does not change …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"14"}},{"t":"case","label":"Howlett ex rel. Howlett v. Rose","cite":"496 U.S. 356","y":1990,"id":"1989/89-5383","sc":1,"sum":"A state-law \"sovereign immunity\" defense is not available to a school board in a § 1983 action brought in a state court that otherwise has jurisdiction when such defense would not be available if the action were brought in a federal forum.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"1"}},{"t":"case","label":"Knox v. Serv. Emps. Int’l Union, Local 1000","cite":"567 U.S. 298","y":2012,"id":"2011/10-1121","sc":1,"sum":"The Court found that, under the First Amendment, public-sector unions are not permitted to impose a special assessment fee without the consent of the member upon whom it is imposed.","sumSrc":"Oyez","by":{"3":"22"}},{"t":"case","label":"Larson v. Valente","cite":"456 U.S. 228","y":1982,"id":"1981/80-1666","sc":1,"sum":"The Court held that the fifty percent rule clearly distinguished between denominations and created denominational preferences within the law, and it did not serve a compelling government interest. The Court also held that the Act failed the three-part test established in Lemon v. Kurtzman by fostering the government entanglement in religion.","sumSrc":"Oyez","by":{"3":"20"}},{"t":"case","label":"Obergefell v. Wymyslo","cite":"962 F. Supp. 2d 968","y":2013,"court":"S.D. Ohio","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/962/968/","by":{"3":"13"}},{"t":"case","label":"Planned Parenthood of Se. Pa. v. Casey","cite":"505 U.S 833","y":1992,"url":"https://www.courtlistener.com/c/U.S/505/833/","by":{"3":"8"}},{"t":"case","label":"Rezzonico v. H & R Block, Inc.","cite":"182 F.3d 144","y":1999,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/182/144/","by":{"3":"14"}},{"t":"case","label":"Simon v. E. Ky. Welfare Rights Org.","cite":"426 U.S. 26","y":1976,"id":"1975/74-1124","sc":1,"sum":"The District Court should have granted petitioners' motion to dismiss because respondents failed to establish their standing to bring this suit.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"19"}},{"t":"case","label":"Sniadach v. Fam. Fin. Corp. of Bay View","cite":"395 U.S. 337","y":1969,"id":"1968/130","sc":1,"op":1,"sum":"Wisconsin's prejudgment garnishment of wages procedure, with its obvious taking of property without notice and prior hearing, violates the fundamental principles of procedural due process. Pp. 339-342. 37 Wis. 2d 163, 154 N. W. 2d 259, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"13"}},{"t":"case","label":"Sonicraft, Inc. v. NLRB","cite":"814 F.2d 385","y":1987,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/814/385/","by":{"3":"14"}},{"t":"case","label":"Telescope Media Grp. v. Lucero","cite":"936 F.3d 740","y":2019,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/936/740/","by":{"3":"9"}},{"t":"case","label":"United States v. Heller","cite":"957 F.2d 26","y":1992,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/957/26/","sum":"Holding that the term “judicial officer” “mean[s] a judge, not an employee in the office of the clerk”.","sumSrc":"brief:3","by":{"3":"14"}},{"t":"case","label":"United States v. Unger","cite":"700 F.2d 445","y":1983,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/700/445/","by":{"3":"14"}},{"t":"case","label":"Whole Woman’s Health v. Hellerstedt","cite":"136 S. Ct. 2292","y":2016,"id":"2015/15-274","sc":1,"sum":"The Court determined that the regulations at issue unconstitutionally imposed an undue burden on women seeking abortions because they created a substantial burden and did not actually serve the stated government interest.","sumSrc":"Oyez","by":{"3":"3"}},{"t":"rule","label":"Fed. R. Civ. P. 21","url":"https://www.law.cornell.edu/rules/frcp/rule_21","by":{"3":"23"}},{"t":"rule","label":"Fed. R. Civ. P. 65","url":"https://www.law.cornell.edu/rules/frcp/rule_65","subs":["(d)(2)"],"by":{"3":"21"}}]};